(function() {
    'use strict';

    class CityManagerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CityManager: Municipal Governance';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'Round 1: Immediate Priorities and Budget Allocation',
                    description: '<b>February 2025.</b> You have just taken office as the government of San Marcos.<br><br>' +
                        '<b>Citizen Survey Results:</b> Water (45% say critical), Transport (35%), Security (20%).<br>' +
                        'Current water satisfaction is only 35%. The aqueduct is 30 years old with 35% leakage.<br><br>' +
                        '<b>Events:</b><br>' +
                        '- The Colombian Water Authority warns: invest USD 50M+ in the aqueduct or risk system failure during dry season.<br>' +
                        '- A civil society coalition requests participatory budgeting (5% of budget allocated through citizen votes).<br>' +
                        '- The municipal council is debating a property tax increase to generate additional revenue.<br><br>' +
                        '<b>Key Question:</b> How do you allocate the USD 480M budget across competing priorities?'
                },
                {
                    title: 'Round 2: Service Delivery and Citizen Engagement',
                    description: '<b>Mid-2025. External shocks test your administration.</b><br><br>' +
                        '<b>Events:</b><br>' +
                        '- <b>Drought declared:</b> Water supply drops 25%. Poor neighborhoods face severe rationing unless you invested in infrastructure.<br>' +
                        '- <b>Transport strike threat:</b> Bus drivers demand a 12% wage increase. A strike would affect 8M daily rides and cost USD 100M/day in economic losses.<br>' +
                        '- <b>Equity tension:</b> Zona Norte (wealthy) demands parks and security upgrades. Zona Sur (poor) still lacks basic water and sanitation.<br><br>' +
                        '<b>Key Question:</b> How do you deliver services? Do you engage citizens in decisions? How do you address equity?'
                },
                {
                    title: 'Round 3: Long-Term Sustainability and Fiscal Planning',
                    description: '<b>Late 2025. Elections loom and major decisions are ahead.</b><br><br>' +
                        '<b>Events:</b><br>' +
                        '- <b>Metro opportunity:</b> An international development bank offers USD 200M for metro expansion (requires municipal matching funds). The metro would serve 1M daily riders.<br>' +
                        '- <b>Economic slowdown:</b> GDP growth forecast drops from 3.5% to 1.5%. Tax revenue could fall 8-12%.<br>' +
                        '- <b>Credit rating review:</b> Current rating BB+. If debt-to-revenue exceeds 150%, a downgrade to BB would raise borrowing costs from 5% to 8%.<br><br>' +
                        '<b>Key Question:</b> What is your long-term vision? Can you invest in transformational infrastructure while maintaining fiscal health?'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 480,
                    debt: 420,
                    totalRevenue: 480,
                    debtToRevenue: 87.5,
                    citizenSatisfaction: 42,
                    waterSatisfaction: 35,
                    transportSatisfaction: 48,
                    securitySatisfaction: 40,
                    educationSatisfaction: 52,
                    equityIndex: 0.57,
                    fiscalHealth: 0.65,
                    taxRate: 0.6,
                    currentServiceModel: 'inhouse',
                    currentEngagement: 'none',
                    cumulativeDebt: 420,
                    droughtActive: false,
                    strikeRisk: false,
                    recessionActive: false,
                    satisfactionHistory: [],
                    fiscalHistory: [],
                    equityHistory: [],
                    debtHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    waterBudget: 50,
                    transportBudget: 65,
                    taxRate: 0.6,
                    serviceModel: 'inhouse',
                    engagement: 'none',
                    newDebt: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var waterInput = document.getElementById('waterBudgetInput');
            if (waterInput) decisions.waterBudget = parseFloat(waterInput.value);

            var transportInput = document.getElementById('transportBudgetInput');
            if (transportInput) decisions.transportBudget = parseFloat(transportInput.value);

            var taxSelect = document.getElementById('taxRateSelect');
            if (taxSelect) decisions.taxRate = parseFloat(taxSelect.value);

            var serviceSelect = document.getElementById('serviceModelSelect');
            if (serviceSelect) decisions.serviceModel = serviceSelect.value;

            var engageSelect = document.getElementById('engagementSelect');
            if (engageSelect) decisions.engagement = engageSelect.value;

            var debtInput = document.getElementById('debtInput');
            if (debtInput) decisions.newDebt = parseFloat(debtInput.value) || 0;

            if (!decisions.waterBudget || decisions.waterBudget < 40 || decisions.waterBudget > 70) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('water_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.transportBudget || decisions.transportBudget < 50 || decisions.transportBudget > 90) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('transport_warning'), 'warning'
                );
                return false;
            }

            var taxBonus = 0;
            if (decisions.taxRate === 0.8) taxBonus = 27;
            if (decisions.taxRate >= 1.0) taxBonus = 53;
            var totalAvailable = 360 + taxBonus;
            var allocated = decisions.waterBudget + decisions.transportBudget;

            if (allocated > totalAvailable) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceeded_warning'), 'warning'
                );
                return false;
            }

            if (decisions.newDebt < 0 || decisions.newDebt > 200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('debt_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var taxBonus = 0;
            if (d.taxRate === 0.8) taxBonus = 27;
            if (d.taxRate >= 1.0) taxBonus = 53;

            var totalOperating = 360 + taxBonus;
            var totalCapital = 120 + d.newDebt;
            var totalBudget = totalOperating + totalCapital;

            var remaining = totalOperating - d.waterBudget - d.transportBudget;
            var securityBudget = remaining * 0.22;
            var educationBudget = remaining * 0.32;
            var healthBudget = remaining * 0.22;
            var parksBudget = remaining * 0.12;
            var adminBudget = remaining * 0.12;

            var participatoryCost = 0;
            if (d.engagement === 'participatory') {
                participatoryCost = totalOperating * 0.05;
            }

            var deliveryQuality = 0.75;
            var deliveryCost = d.waterBudget;
            var equityPenalty = 0;
            if (d.serviceModel === 'inhouse') {
                deliveryQuality = 0.72;
                deliveryCost = d.waterBudget;
                equityPenalty = 0;
            } else if (d.serviceModel === 'outsource') {
                deliveryQuality = 0.85;
                deliveryCost = d.waterBudget * 0.88;
                equityPenalty = -0.12;
            } else if (d.serviceModel === 'ppp') {
                deliveryQuality = 0.80;
                deliveryCost = d.waterBudget * 0.93;
                equityPenalty = -0.05;
            }

            var engagementBonus = 1.0;
            if (d.engagement === 'basic') engagementBonus = 1.04;
            if (d.engagement === 'participatory') engagementBonus = 1.10;

            var droughtPenalty = 1.0;
            if (round >= 2) {
                ds.droughtActive = true;
                if (d.waterBudget < 55) {
                    droughtPenalty = 0.70;
                } else if (d.waterBudget < 62) {
                    droughtPenalty = 0.85;
                } else {
                    droughtPenalty = 0.95;
                }
            }

            var strikePenalty = 1.0;
            if (round >= 2) {
                ds.strikeRisk = true;
                if (d.transportBudget < 70) {
                    strikePenalty = 0.65;
                } else if (d.transportBudget < 80) {
                    strikePenalty = 0.85;
                } else {
                    strikePenalty = 1.0;
                }
            }

            var recessionPenalty = 1.0;
            if (round >= 3) {
                ds.recessionActive = true;
                recessionPenalty = 0.90;
                totalOperating = totalOperating * 0.90;
            }

            var waterTarget = 60;
            var waterSat = Math.min(100, (d.waterBudget / waterTarget) * deliveryQuality * droughtPenalty * engagementBonus * 100);
            waterSat = Math.round(Math.max(10, waterSat));

            var transportTarget = 75;
            var transportSat = Math.min(100, (d.transportBudget / transportTarget) * strikePenalty * engagementBonus * 100);
            transportSat = Math.round(Math.max(10, transportSat));

            var securityTarget = 45;
            var securitySat = Math.min(100, (securityBudget / securityTarget) * engagementBonus * recessionPenalty * 100);
            securitySat = Math.round(Math.max(10, securitySat));

            var educationTarget = 100;
            var educationSat = Math.min(100, (educationBudget / educationTarget) * engagementBonus * recessionPenalty * 100);
            educationSat = Math.round(Math.max(10, educationSat));

            var overallSat = Math.round(
                waterSat * 0.30 +
                transportSat * 0.25 +
                securitySat * 0.20 +
                educationSat * 0.15 +
                (d.engagement === 'participatory' ? 10 : d.engagement === 'basic' ? 4 : 0)
            );
            overallSat = Math.min(100, Math.max(10, overallSat));

            var taxBacklash = 0;
            if (d.taxRate === 0.8) taxBacklash = -3;
            if (d.taxRate >= 1.0) taxBacklash = -7;
            overallSat = Math.max(10, overallSat + taxBacklash);

            var baseEquity = 0.57;
            var equityDelta = 0;
            if (d.waterBudget >= 60) equityDelta += 0.08;
            else if (d.waterBudget >= 55) equityDelta += 0.04;
            if (d.engagement === 'participatory') equityDelta += 0.10;
            else if (d.engagement === 'basic') equityDelta += 0.04;
            equityDelta += equityPenalty;
            if (d.transportBudget >= 75) equityDelta += 0.03;

            var prevEquity = ds.equityIndex || baseEquity;
            var newEquity = Math.min(0.95, Math.max(0.30, prevEquity + equityDelta));
            newEquity = Math.round(newEquity * 100) / 100;

            var newDebtTotal = ds.cumulativeDebt + d.newDebt;
            var currentRevenue = (360 + taxBonus) * recessionPenalty + 120;
            var newDebtToRevenue = Math.round((newDebtTotal / currentRevenue) * 100 * 10) / 10;

            var operatingBalance = totalOperating - d.waterBudget - d.transportBudget - securityBudget - educationBudget - healthBudget - parksBudget - adminBudget - participatoryCost;
            var debtServiceCost = newDebtTotal * 0.06;
            var netFiscal = operatingBalance - (debtServiceCost / 12);

            var fiscalScore = (1 - (newDebtToRevenue / 200)) * (netFiscal >= 0 ? 1.0 : 0.7);
            fiscalScore = Math.min(1.0, Math.max(0.1, fiscalScore));
            fiscalScore = Math.round(fiscalScore * 100) / 100;

            var fiscalLabel = 'Stable';
            if (fiscalScore >= 0.75) fiscalLabel = 'Healthy';
            else if (fiscalScore >= 0.50) fiscalLabel = 'Stable';
            else if (fiscalScore >= 0.35) fiscalLabel = 'At Risk';
            else fiscalLabel = 'Crisis';

            ds.cash = Math.round(totalBudget);
            ds.debt = Math.round(newDebtTotal);
            ds.totalRevenue = Math.round(currentRevenue);
            ds.debtToRevenue = newDebtToRevenue;
            ds.citizenSatisfaction = overallSat;
            ds.waterSatisfaction = waterSat;
            ds.transportSatisfaction = transportSat;
            ds.securitySatisfaction = securitySat;
            ds.educationSatisfaction = educationSat;
            ds.equityIndex = newEquity;
            ds.fiscalHealth = fiscalScore;
            ds.taxRate = d.taxRate;
            ds.currentServiceModel = d.serviceModel;
            ds.currentEngagement = d.engagement;
            ds.cumulativeDebt = newDebtTotal;

            ds.satisfactionHistory.push(overallSat);
            ds.fiscalHistory.push(fiscalScore);
            ds.equityHistory.push(newEquity);
            ds.debtHistory.push(newDebtToRevenue);

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: state.currentPeriod,
                totalBudget: totalBudget,
                waterBudget: d.waterBudget,
                transportBudget: d.transportBudget,
                otherBudget: Math.round(remaining),
                taxRevenue: Math.round(360 + taxBonus),
                newDebt: d.newDebt,
                satisfaction: overallSat,
                waterSat: waterSat,
                transportSat: transportSat,
                equityIndex: newEquity,
                debtToRevenue: newDebtToRevenue,
                fiscalHealth: fiscalScore,
                fiscalLabel: fiscalLabel,
                serviceModel: d.serviceModel,
                engagement: d.engagement
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.cash',
                (v) => '$' + Math.round(v) + 'M');
            uiManager.bind('debtRatioDisplay', 'domainState.debtToRevenue',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('satisfactionDisplay', 'domainState.citizenSatisfaction',
                (v) => Math.round(v) + '%');
            uiManager.bind('equityDisplay', 'domainState.equityIndex',
                (v) => v.toFixed(2));
            uiManager.bind('fiscalDisplay', 'domainState.fiscalHealth',
                function(v) {
                    if (v >= 0.75) return 'Healthy';
                    if (v >= 0.50) return 'Stable';
                    if (v >= 0.35) return 'At Risk';
                    return 'Crisis';
                });
        }

        getChartConfig() {
            return {
                satisfactionChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Citizen Satisfaction (%)',
                            data: [],
                            borderColor: '#f39c12',
                            backgroundColor: 'rgba(243,156,18,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'Equity Index',
                            data: [],
                            borderColor: '#8e44ad',
                            backgroundColor: 'rgba(142,68,173,0.1)',
                            borderWidth: 3,
                            fill: false,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Satisfaction and Equity Over Time' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: 'Satisfaction (%)' } },
                            y1: { position: 'right', beginAtZero: true, max: 1, title: { display: true, text: 'Equity Index' }, grid: { drawOnChartArea: false } }
                        }
                    }
                },
                fiscalChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Debt-to-Revenue (%)',
                            data: [],
                            backgroundColor: 'rgba(231,76,60,0.6)',
                            borderColor: '#e74c3c',
                            borderWidth: 2
                        }, {
                            label: 'Fiscal Health Score',
                            data: [],
                            backgroundColor: 'rgba(36,113,163,0.6)',
                            borderColor: '#2471a3',
                            borderWidth: 2,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Fiscal Health Over Time' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 200, title: { display: true, text: 'Debt-to-Revenue (%)' } },
                            y1: { position: 'right', beginAtZero: true, max: 1, title: { display: true, text: 'Fiscal Score' }, grid: { drawOnChartArea: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.satisfactionHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                satisfactionChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.satisfactionHistory },
                        { data: state.domainState.equityHistory.map(function(v) { return Math.round(v * 100) / 100; }) }
                    ]
                },
                fiscalChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.debtHistory },
                        { data: state.domainState.fiscalHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastRound = history[history.length - 1];
            var results = lastRound.results || {};
            var finalSat = results.satisfaction || 0;
            var finalEquity = results.equityIndex || 0;
            var finalFiscal = results.fiscalHealth || 0;
            var finalDebt = results.debtToRevenue || 0;

            var composite = (finalSat / 100) * 0.35 + finalFiscal * 0.25 + finalEquity * 0.20 + (1 - Math.min(finalDebt, 200) / 200) * 0.10 + (finalEquity > 0.7 ? 0.10 : finalEquity > 0.5 ? 0.05 : 0);

            var performance = 'Needs Improvement';
            if (composite >= 0.70) performance = 'Excellent Mayor';
            else if (composite >= 0.55) performance = 'Good Administrator';
            else if (composite >= 0.40) performance = 'Average Performance';

            var insights = [];
            if (finalSat >= 65) insights.push('Strong citizen satisfaction indicates responsive governance.');
            if (finalSat < 45) insights.push('Low citizen satisfaction suggests unmet service needs.');
            if (finalEquity >= 0.75) insights.push('Excellent equity outcomes — poor neighborhoods are being served.');
            if (finalEquity < 0.55) insights.push('Equity remains a critical concern — service disparities persist.');
            if (finalFiscal >= 0.70) insights.push('Healthy fiscal position provides room for future investment.');
            if (finalFiscal < 0.40) insights.push('Fiscal health is at risk — debt management needs attention.');
            if (finalDebt > 150) insights.push('Debt-to-revenue ratio is dangerously high. Credit downgrade is likely.');

            return {
                finalSatisfaction: finalSat,
                finalEquity: finalEquity,
                finalFiscal: finalFiscal,
                finalDebtRatio: finalDebt,
                compositeScore: Math.round(composite * 100),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.debtToRevenue > 130) return window.mySimulation.t('hint_debt_high');
            if (results.satisfaction < 40) return window.mySimulation.t('hint_low_satisfaction');
            if (results.equityIndex < 0.50) return window.mySimulation.t('hint_low_equity');
            if (results.waterSat < 40) return window.mySimulation.t('hint_water_crisis');
            if (results.fiscalHealth < 0.40) return window.mySimulation.t('hint_fiscal_crisis');
            if (results.satisfaction >= 65 && results.fiscalHealth >= 0.65) return window.mySimulation.t('hint_good_balance');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.totalBudget', label: 'Budget (M)', i18nKey: 'col_budget', formatter: function(v) { return '$' + v; } },
                { key: 'results.waterBudget', label: 'Water (M)', i18nKey: 'col_water', formatter: function(v) { return '$' + v; } },
