        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = '<h4>' + round.title + '</h4>' + round.description;
            }

            var waterInput = document.getElementById('waterBudgetInput');
            var transportInput = document.getElementById('transportBudgetInput');
            var taxSelect = document.getElementById('taxRateSelect');
            var debtInput = document.getElementById('debtInput');

            var self = this;
            var updateRemaining = function() {
                var w = parseFloat(waterInput ? waterInput.value : 50) || 50;
                var t = parseFloat(transportInput ? transportInput.value : 65) || 65;
                var tax = parseFloat(taxSelect ? taxSelect.value : 0.6) || 0.6;
                var taxBonus = 0;
                if (tax === 0.8) taxBonus = 27;
                if (tax >= 1.0) taxBonus = 53;
                var total = 360 + taxBonus;
                var rem = total - w - t;
                var remEl = document.getElementById('remainingBudgetDisplay');
                if (remEl) {
                    remEl.textContent = '$' + Math.round(rem) + 'M';
                    remEl.style.color = rem < 0 ? '#e74c3c' : '#27ae60';
                }
            };

            if (waterInput) waterInput.addEventListener('input', updateRemaining);
            if (transportInput) transportInput.addEventListener('input', updateRemaining);
            if (taxSelect) taxSelect.addEventListener('change', updateRemaining);

            updateRemaining();
        }
